ALTER TABLE rmas ${dropCheck} ck_rmas_status;
ALTER TABLE rma_status_history ${dropCheck} ck_rma_status_history_status;
ALTER TABLE kanban_views ${dropCheck} ck_kanban_views_status;
ALTER TABLE rmas MODIFY COLUMN status VARCHAR(60) NOT NULL;
ALTER TABLE rma_status_history MODIFY COLUMN status VARCHAR(60) NOT NULL;
ALTER TABLE kanban_views MODIFY COLUMN status VARCHAR(60);
ALTER TABLE rmas ADD COLUMN related_rma_id BIGINT;
ALTER TABLE rmas ADD CONSTRAINT fk_rmas_related FOREIGN KEY (related_rma_id) REFERENCES rmas(id) ON DELETE SET NULL;
ALTER TABLE rma_status_history ADD COLUMN status_label VARCHAR(120);
ALTER TABLE rma_status_history ADD COLUMN workflow_name VARCHAR(120);
ALTER TABLE rma_status_history ADD COLUMN workflow_version BIGINT;
UPDATE rma_status_history SET status_label=CASE status
WHEN 'RECEIVED' THEN 'Recebido'
WHEN 'TRIAGE' THEN 'Triagem'
WHEN 'IN_DIAGNOSIS' THEN 'Diagnóstico'
WHEN 'WAITING_PART' THEN 'Aguardando peça'
WHEN 'IN_REPAIR' THEN 'Reparo'
WHEN 'IN_TESTS' THEN 'Testes'
WHEN 'COMPLETED' THEN 'Concluído'
WHEN 'RETURNED' THEN 'Devolvido'
WHEN 'IRREPARABLE' THEN 'Sem conserto'
END, workflow_name='Fluxo de RMA', workflow_version=1;
CREATE TABLE workflow_config (id BIGINT PRIMARY KEY, version BIGINT NOT NULL, revision BIGINT NOT NULL, published_document LONGTEXT NOT NULL, draft_document LONGTEXT);
CREATE TABLE workflow_versions (version BIGINT PRIMARY KEY, document LONGTEXT NOT NULL);
