CREATE TABLE checklist_templates (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, document LONGTEXT NOT NULL);
CREATE TABLE checklist_template_versions (template_id BIGINT NOT NULL, version BIGINT NOT NULL, document LONGTEXT NOT NULL, PRIMARY KEY(template_id,version), CONSTRAINT fk_checklist_versions_template FOREIGN KEY(template_id) REFERENCES checklist_templates(id));
CREATE TABLE rma_checklists (id BIGINT AUTO_INCREMENT PRIMARY KEY, rma_id BIGINT NOT NULL, template_code VARCHAR(60) NOT NULL, document LONGTEXT NOT NULL, CONSTRAINT fk_rma_checklists_rma FOREIGN KEY(rma_id) REFERENCES rmas(id) ON DELETE CASCADE);
CREATE INDEX idx_rma_checklists_rma ON rma_checklists(rma_id,template_code,id);
CREATE TABLE rma_approvals (id BIGINT AUTO_INCREMENT PRIMARY KEY, rma_id BIGINT NOT NULL, code VARCHAR(60) NOT NULL, document LONGTEXT NOT NULL, CONSTRAINT fk_rma_approvals_rma FOREIGN KEY(rma_id) REFERENCES rmas(id) ON DELETE CASCADE);
CREATE INDEX idx_rma_approvals_rma ON rma_approvals(rma_id,code,id);
